import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    t = int(next(it))

    for _ in range(t):
        n = int(next(it))
        m = int(next(it))

        matrix = []
        for _ in range(n):
            row = [int(next(it)) for _ in range(m)]
            matrix.append(row)

        found = False
        answer = ""
        k = -1

        # Try all possible k values
        for cut in range(1, m):
            # Compute min_left for each row
            min_left = [min(row[:cut]) for row in matrix]

            # Compute max_right for each row
            max_right = [max(row[cut:]) for row in matrix]

            # Try to find a valid coloring
            # We need at least one red and one blue

            # Find rows that could be red (min_left > max_left of all other rows)
            red_candidates = []
            for i in range(n):
                # Check if this row can be red
                # min_left[i] > max_left of all other rows
                max_other_left = max(min_left[j] for j in range(n) if j != i)
                if min_left[i] > max_other_left:
                    red_candidates.append(i)

            # Find rows that could be blue (max_right > min_right of all other rows)
            blue_candidates = []
            for i in range(n):
                # Check if this row can be blue
                # max_right[i] > min_right of all other rows
                min_other_right = min(max_right[j] for j in range(n) if j != i)
                if max_right[i] > min_other_right:
                    blue_candidates.append(i)

            # If we have at least one red and one blue candidate
            if red_candidates and blue_candidates:
                # Try to color them
                # Pick the first red candidate and first blue candidate
                red_idx = red_candidates[0]
                blue_idx = blue_candidates[0]

                # Check if this coloring works
                # All red rows: min_left[row] > max_left of blue rows
                # All blue rows: max_right[row] > min_right of red rows

                # Get all red rows (including the chosen one)
                red_rows = [i for i in range(n) if min_left[i] > max_left[blue_idx]]

                # Get all blue rows (including the chosen one)
                blue_rows = [i for i in range(n) if max_right[i] > min_right[red_idx]]

                # Check if all red rows are indeed red
                for i in red_rows:
                    if i not in red_rows:
                        break
                else:
                    # Check if all blue rows are indeed blue
                    for i in blue_rows:
                        if i not in blue_rows:
                            break
                    else:
                        # Check if there's at least one red and one blue
                        if red_rows and blue_rows:
                            # Check if the coloring is valid
                            valid = True
                            for i in red_rows:
                                for j in blue_rows:
                                    if matrix[i][0] <= matrix[j][0]:
                                        valid = False
                                        break
                                if not valid:
                                    break
                            if valid:
                                for i in blue_rows:
                                    for j in red_rows:
                                        if matrix[i][0] >= matrix[j][0]:
                                            valid = False
                                            break
                                    if not valid:
                                        break
                                if valid:
                                    # Found a solution
                                    found = True
                                    answer = "YES"
                                    k = cut

                                    # Build the coloring string
                                    coloring = ["R" if i in red_rows else "B" for i in range(n)]
                                    answer += "\n" + ''.join(coloring)
                                    answer += "\n" + str(k)
                                    break

                if found:
                    break

        if not found:
            answer = "NO"

        print(answer)

if __name__ == "__main__":
    solve()
