def readints():
    return list(map(int, sys.stdin.readline().split()))

def cross(o, a, b):
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

def segments_intersect(a1, a2, b1, b2):
    # Check if line segments a1-a2 and b1-b2 intersect
    # Using cross product method
    ccw1 = cross(a1, a2, b1)
    ccw2 = cross(a1, a2, b2)
    ccw3 = cross(b1, b2, a1)
    ccw4 = cross(b1, b2, a2)

    if (ccw1 > 0 and ccw2 < 0) or (ccw1 < 0 and ccw2 > 0):
        return True
    if (ccw3 > 0 and ccw4 < 0) or (ccw3 < 0 and ccw4 > 0):
        return True

    # Check if endpoints lie on the other segment
    if ccw1 == 0 and cross(b1, b2, a1) <= 0:
        return True
    if ccw2 == 0 and cross(b1, b2, a2) <= 0:
        return True
    if ccw3 == 0 and cross(a1, a2, b1) <= 0:
        return True
    if ccw4 == 0 and cross(a1, a2, b2) <= 0:
        return True

    return False

def solve():
    n, H = readints()
    points = [tuple(map(int, sys.stdin.readline().split())) for _ in range(n)]

    eye = (points[-1][0], points[-1][1] + H)

    total = 0.0

    for i in range(n - 1):
        x1, y1 = points[i]
        x2, y2 = points[i + 1]

        # Check if line from Eye to segment intersects the polyline
        wearing_cloak = False

        for j in range(n - 1):
            a1 = points[j]
            a2 = points[j + 1]

            # Check if line from Eye to segment intersects polyline segment
            # This is more complex - we need to check if the line from Eye to the segment intersects
            # the polyline segment at any point

            # For now, let's just check the endpoints
            # This is not correct, but let's see

            if segments_intersect(eye, (x1, y1), a1, a2):
                wearing_cloak = True
                break
            if segments_intersect(eye, (x2, y2), a1, a2):
                wearing_cloak = True
                break

        if wearing_cloak:
            total += ((x2 - x1)**2 + (y2 - y1)**2)**0.5

    print(total)

solve()
