import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    t = int(data[0])
    out_lines = []
    idx = 1

    for _ in range(t):
        n = int(data[idx])
        idx += 1

        if n == 1:
            out_lines.append("1")
        else:
            # Generate numbers with lengths from n+1 to 2n-1, all made of 1's
            result = []
            for length in range(n + 1, 2 * n):
                result.append("1" * length)
            out_lines.append(" ".join(result))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
"}

