n, k = map(int, input().split())
line = input().strip()

# Find positions of G and T
g_pos = line.index('G')
t_pos = line.index('T')

# Build adjacency list
adj = [[] for _ in range(n)]
for i in range(n):
    if line[i] == '#':
        continue
    # Jump to the right
    if i + k < n and line[i + k] != '#':
        adj[i].append(i + k)
    # Jump to the left
    if i - k >= 0 and line[i - k] != '#':
        adj[i].append(i - k)

# BFS to find path from G to T
current = g_pos
visited = set()
visited.add(current)

while current != t_pos:
    found = False
    for neighbor in adj[current]:
        if neighbor not in visited:
            visited.add(neighbor)
            current = neighbor
            found = True
            break
    if not found:
        break

if current == t_pos:
    print("YES")
else:
    print("NO")
"}

