import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    d = int(data[0])
    n = int(data[1])
    m = int(data[2])

    sofas = []
    idx = 3
    for i in range(d):
        x1 = int(data[idx])
        y1 = int(data[idx+1])
        x2 = int(data[idx+2])
        y2 = int(data[idx+3])
        sofas.append((x1, y1, x2, y2))
        idx += 4

    cntl = int(data[idx])
    cntr = int(data[idx+1])
    cntt = int(data[idx+2])
    cntb = int(data[idx+3])

    # For each sofa, count left, right, top, bottom
    for i, (x1, y1, x2, y2) in enumerate(sofas):
        min_x = min(x1, x2)
        max_x = max(x1, x2)
        min_y = min(y1, y2)
        max_y = max(y1, y2)

        # Count left: same row, any cell has smaller x
        left = 0
        for j, (xj1, yj1, xj2, yj2) in enumerate(sofas):
            if i == j:
                continue
            if yj1 == yj2 == y1 == y2:
                # Same row
                if min(xj1, xj2) < min_x:
                    left += 1

        # Count right: same row, any cell has larger x
        right = 0
        for j, (xj1, yj1, xj2, yj2) in enumerate(sofas):
            if i == j:
                continue
            if yj1 == yj2 == y1 == y2:
                # Same row
                if max(xj1, xj2) > max_x:
                    right += 1

        # Count top: same column, any cell has smaller y
        top = 0
        for j, (xj1, yj1, xj2, yj2) in enumerate(sofas):
            if i == j:
                continue
            if xj1 == xj2 == x1 == x2:
                # Same column
                if min(yj1, yj2) < min_y:
                    top += 1

        # Count bottom: same column, any cell has larger y
        bottom = 0
        for j, (xj1, yj1, xj2, yj2) in enumerate(sofas):
            if i == j:
                continue
            if xj1 == xj2 == x1 == x2:
                # Same column
                if max(yj1, yj2) > max_y:
                    bottom += 1

        if left == cntl and right == cntr and top == cntt and bottom == cntb:
            print(i + 1)
            return

    print(-1)

if __name__ == "__main__":
    solve()
"}

