n = int(input())
snacks = list(map(int, input().split()))

fallen = set()
output = [[] for _ in range(n)]

current_max = n  # The largest snack we can place

for day in range(n):
    snack = snacks[day]
    fallen.add(snack)

    # Check if we can place snacks
    while True:
        # Find the largest snack that can be placed
        can_place = False
        for s in range(current_max, 0, -1):
            if s in fallen:
                # Check if all larger snacks have fallen
                all_larger_fallen = True
                for larger in range(s+1, n+1):
                    if larger not in fallen:
                        all_larger_fallen = False
                        break

                if all_larger_fallen:
                    # Place this snack
                    output[day].append(s)
                    fallen.remove(s)
                    current_max = s - 1
                    can_place = True
                    break

        if not can_place:
            break

for line in output:
    print(' '.join(map(str, line)))
"}

