import sys

def reverse_directions(instructions):
    """Reverse the directions: flip turns and reverse order"""
    reversed_instructions = []

    # The first instruction is always "Begin on XXX"
    reversed_instructions.append(instructions[0])

    # Process the rest of the instructions
    for i in range(len(instructions) - 1, 0, -1):
        instruction = instructions[i]
        if instruction.startswith("Left on "):
            reversed_instructions.append("Right on " + instruction[8:])
        elif instruction.startswith("Right on "):
            reversed_instructions.append("Left on " + instruction[9:])
        else:
            # This should never happen
            reversed_instructions.append(instruction)

    return reversed_instructions

def main():
    data = sys.stdin.read().strip().split('\n')
    if not data:
        return

    idx = 0
    T = int(data[idx])
    idx += 1

    for _ in range(T):
        N = int(data[idx])
        idx += 1

        instructions = []
        for _ in range(N):
            instructions.append(data[idx])
            idx += 1

        reversed_instructions = reverse_directions(instructions)

        for instr in reversed_instructions:
            print(instr)

        # Print a blank line after each test case
        if _ < T - 1:
            print()

if __name__ == "__main__":
    main()
