# Find the digit with minimum cost
min_cost = min(a)
cheapest_digit = a.index(min_cost) + 1  # 1-indexed

if min_cost > v:
    print(-1)
else:
    count = v // min_cost
    leftover = v % min_cost

    if count == 0:
        print(-1)
    else:
        # Start with all cheapest digits
        result = [str(cheapest_digit)] * count

        # Try to improve lexicographically
        for i in range(count):
            # Try to replace digit at position i with a more expensive digit
            for d in range(1, 10):
                if d == cheapest_digit:
                    continue
                cost = a[d - 1]
                if leftover >= cost:
                    # Replace
                    result[i] = str(d)
                    leftover -= cost
                    break

        print(''.join(result))
