# Function to apply median smoothing
def apply_smoothing(seq):
    n = len(seq)
    new_seq = [0] * n
    new_seq[0] = seq[0]
    new_seq[n-1] = seq[n-1]

    for i in range(1, n-1):
        # Median of three values
        # If at least two 0s, median is 0; else 1
        if seq[i-1] == 0 and seq[i] == 0 or seq[i] == 0 and seq[i+1] == 0 or seq[i-1] == 0 and seq[i+1] == 0:
            new_seq[i] = 0
        else:
            new_seq[i] = 1

    return new_seq

# Check if sequence is stable
def is_stable(seq):
    n = len(seq)
    for i in range(1, n-1):
        if seq[i] != median(seq[i-1], seq[i], seq[i+1]):
            return False
    return True

# Median function
def median(a, b, c):
    if a == 0 and b == 0 or b == 0 and c == 0 or a == 0 and c == 0:
        return 0
    else:
        return 1

# Apply smoothing until stable
steps = 0
while True:
    if is_stable(a):
        break
    a = apply_smoothing(a)
    steps += 1

print(steps)
print(' '.join(map(str, a)))
"}

