import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    N = int(data[0])
    M = int(data[1])

    # Build adjacency list
    adj = [[] for _ in range(N)]
    for i in range(M):
        u = int(data[2 + 2*i]) - 1
        v = int(data[2 + 2*i + 1]) - 1
        adj[u].append(v)
        adj[v].append(u)

    # Check for clique of size 5
    for u in range(N):
        if len(adj[u]) >= 4:
            neighbors = adj[u]
            # Check if these 4 neighbors form a clique
            if len(set(neighbors)) == 4:
                # Check if all neighbors are connected to each other
                is_clique = True
