n, q = map(int, input().split())

# Track busy intervals for each server
busy_intervals = [[] for _ in range(n)]

for _ in range(q):
    ti, ki, di = map(int, input().split())

    # Find unoccupied servers at time ti
    unoccupied = []
    for server_id in range(n):
        # Check if server is busy at time ti
        busy = False
        for start, end in busy_intervals[server_id]:
            if start <= ti <= end:
                busy = True
                break
        if not busy:
            unoccupied.append(server_id)

    if len(unoccupied) >= ki:
        # Assign ki smallest IDs
        assigned = unoccupied[:ki]
        # Mark them as busy from ti to ti + di - 1
        for server_id in assigned:
            busy_intervals[server_id].append((ti, ti + di - 1))
        # Output sum of IDs
        print(sum(assigned + 1))  # Convert to 1-indexed IDs
    else:
        print(-1)
"}

