{"code": "
import sys
from itertools import permutations

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    p1, p2, p3, p4, a, b = map(int, data)

    # Generate all 24 permutations of the 4 numbers
    nums = [p1, p2, p3, p4]
    perms = permutations(nums)

    # For each x in [a, b], count how many permutations satisfy f(x) = x
    count = 0
    for x in range(a, b + 1):
        perm_count = 0
        for perm in perms:
            # Apply remainders in this order
            result = x
            for num in perm:
                result = result % num
            if result == x:
                perm_count += 1

        if perm_count >= 7:
            count += 1

    print(count)

if __name__ == "__main__":
    solve()
"}
